mapper.update:
UPDATE public.rta_match m SET synergy_applied_at = CURRENT_TIMESTAMP, synergy_apply_result = 'S' FROM unnest(ARRAY[
#{rid}
]::bigint[]) AS u(rid) WHERE m.replay_id = u.rid

/* rta-queries-batch-meta.clearSummonerRankingMatchFlagsForSeason — 수동 리셋·DDL 후 재집계용: 해당 시즌 rta_match 무거운 스냅 플래그 초기화 */
UPDATE public.rta_match
SET summoner_ranking_applied_at = NULL,
    summoner_ranking_apply_result = NULL
WHERE season_id = #{seasonId}

mapper.select:
WITH pool_filtered AS ( SELECT s.rank_position, s.wizard_id, s.wizard_name, s.country, s.channel_uid, s.score, s.rating_id, s.max_season_score, s.match_count, s.win_count FROM public.rta_agg_summoner_ranking_snap s WHERE s.season_id = #{seasonId}
AND ( (#{countryFilter} = '—' AND (s.country IS NULL OR s.country = '')) OR (#{countryFilter} <> '—' AND s.country = #{countryFilter}) )
), pool_meta AS ( SELECT COUNT(*)::int AS "rankingPoolTotal" FROM pool_filtered ), page AS ( SELECT * FROM pool_filtered ORDER BY rank_position LIMIT #{limit} OFFSET #{offset} ) SELECT pm."rankingPoolTotal", p.rank_position, p.wizard_id, p.wizard_name, p.country, p.channel_uid, p.score, p.rating_id, p.max_season_score, p.match_count, p.win_count FROM pool_meta pm LEFT JOIN page p ON true ORDER BY p.rank_position NULLS LAST

/* rta-queries-batch-meta.selectReplayIdsForSummonerMonsterSnapKeyset — idx_rta_match_summoner_ranking_pending */
SELECT m.replay_id
FROM public.rta_match m
WHERE m.season_id = #{seasonId}
  AND m.summoner_ranking_apply_result IS NULL
  AND m.replay_id > #{afterReplayIdExclusive}
ORDER BY m.replay_id
LIMIT #{limit}

mapper.delete:
/* rta-queries-batch-meta.deleteRtaMonsterDailySnapByDate */
DELETE FROM public.rta_agg_monster_daily_snap
WHERE season_id = #{seasonId}
  AND snap_date = #{snapDate}::date

/* rta-queries-batch-meta.deleteRtaMonsterPickSlotSnapBySeason */
DELETE FROM public.rta_agg_monster_pick_slot_snap
WHERE season_id = #{seasonId}
  AND rating_id = #{ratingId}

mapper.insert:
/* rta-queries-batch-meta.insertRtaMonsterPickSlotSnapForSeason */ INSERT INTO public.rta_agg_monster_pick_slot_snap (season_id, rating_id, unit_master_id, team_side, pick_slot_no, pick_cnt, win_cnt, field_cnt) WITH matches AS ( SELECT mp.replay_id, mp.wizard_id, mp.is_winner::boolean AS is_winner, mp.is_first_pick::boolean AS is_first_pick FROM public.rta_match_participant mp WHERE mp.season_id = #{seasonId}
AND mp.rating_id = #{ratingId}
), picks AS ( SELECT up.unit_master_id, CASE WHEN m.is_first_pick THEN 1 ELSE 2 END::smallint AS team_side, up.pick_slot_no::smallint AS pick_slot_no, m.is_winner FROM public.rta_match_unit_pick up INNER JOIN matches m ON m.replay_id = up.replay_id AND up.wizard_id = m.wizard_id WHERE up.unit_master_id IS NOT NULL AND NOT up.is_banned AND up.pick_slot_no BETWEEN 1 AND 5 ), field AS ( SELECT CASE WHEN m.is_first_pick THEN 1 ELSE 2 END::smallint AS team_side, COUNT(DISTINCT m.replay_id)::integer AS field_cnt FROM matches m GROUP BY 1 ) SELECT #{seasonId}::bigint AS season_id, #{ratingId}::smallint AS rating_id, p.unit_master_id, p.team_side, p.pick_slot_no, COUNT(*)::integer AS pick_cnt, COUNT(*) FILTER (WHERE p.is_winner)::integer AS win_cnt, COALESCE(f.field_cnt, 0) AS field_cnt FROM picks p LEFT JOIN field f ON f.team_side = p.team_side GROUP BY p.unit_master_id, p.team_side, p.pick_slot_no, f.field_cnt ON CONFLICT (season_id, rating_id, unit_master_id, team_side, pick_slot_no) DO UPDATE SET pick_cnt = EXCLUDED.pick_cnt, win_cnt = EXCLUDED.win_cnt, field_cnt = EXCLUDED.field_cnt
